package com.primehr.performancemanagement;
import com.primehr.performancemanagement.api.PerformanceManagementDtos.*;import com.primehr.performancemanagement.application.*;import com.primehr.performancemanagement.domain.*;import com.primehr.shared.exception.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class PerformanceManagementFoundationIntegrationTest{
 @Autowired PerformancePolicyService policies;@Autowired PerformanceCycleService cycles;
 @Test void policyPublishingIsEffectiveDatedImmutableAndRevisionSafe(){PolicyResponse draft=policies.create("TEST-AGENCY",policy("SPMS",null),null);assertThat(draft.status()).isEqualTo("DRAFT");PolicyResponse published=policies.publish("TEST-AGENCY",draft.id(),new PolicyTransition(draft.recordVersion(),LocalDate.of(2026,1,1),null,"Approved agency SPMS"),null);assertThat(policies.effective("TEST-AGENCY",LocalDate.of(2026,6,1)).id()).isEqualTo(published.id());assertThatThrownBy(()->policies.update("TEST-AGENCY",published.id(),policy("SPMS",published.recordVersion()),null)).isInstanceOf(IllegalLifecycleTransitionException.class);PolicyResponse revision=policies.revision("TEST-AGENCY",published.id(),new VersionTransition(published.recordVersion(),"2027 revision"),null);PolicyResponse next=policies.publish("TEST-AGENCY",revision.id(),new PolicyTransition(revision.recordVersion(),LocalDate.of(2027,1,1),null,"Effective 2027"),null);assertThat(next.definitionVersion()).isEqualTo(2);assertThat(policies.get("TEST-AGENCY",published.id()).effectiveTo()).isEqualTo(LocalDate.of(2026,12,31));assertThatThrownBy(()->policies.update("TEST-AGENCY",revision.id(),policy("SPMS",99L),null)).isInstanceOf(OptimisticConflictException.class);}
 @Test void overlappingIndependentPoliciesAreRejected(){PolicyResponse one=policies.create("TEST-AGENCY",policy("ONE",null),null);policies.publish("TEST-AGENCY",one.id(),new PolicyTransition(one.recordVersion(),LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"one"),null);PolicyResponse two=policies.create("TEST-AGENCY",policy("TWO",null),null);assertThatThrownBy(()->policies.publish("TEST-AGENCY",two.id(),new PolicyTransition(two.recordVersion(),LocalDate.of(2026,6,1),LocalDate.of(2027,5,31),"overlap"),null)).hasMessageContaining("already effective");}
 @Test void cycleRequiresExactEffectivePolicyCompleteCalendarAndLifecycle(){PolicyResponse draft=policies.create("TEST-AGENCY",policy("CYCLE",null),null);PolicyResponse policy=policies.publish("TEST-AGENCY",draft.id(),new PolicyTransition(draft.recordVersion(),LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"approved"),null);CycleResponse cycle=cycles.create("TEST-AGENCY",new CycleInput("2026","Performance 2026",LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),policy.id(),"Asia/Manila",null),null);assertThatThrownBy(()->cycles.open("TEST-AGENCY",cycle.id(),new CycleTransition(cycle.recordVersion(),"open"),null)).hasMessageContaining("missing");CycleResponse calendar=cycles.milestones("TEST-AGENCY",cycle.id(),new MilestonesInput(cycle.recordVersion(),calendar()),null);assertThat(calendar.calendarRevision()).isEqualTo(1);assertThat(calendar.recordVersion()).isGreaterThan(cycle.recordVersion());CycleResponse opened=cycles.open("TEST-AGENCY",cycle.id(),new CycleTransition(calendar.recordVersion(),"calendar approved"),null);assertThat(opened.status()).isEqualTo("OPEN");assertThatThrownBy(()->cycles.milestones("TEST-AGENCY",cycle.id(),new MilestonesInput(opened.recordVersion(),calendar()),null)).isInstanceOf(IllegalLifecycleTransitionException.class);CycleResponse closed=cycles.close("TEST-AGENCY",cycle.id(),new CycleTransition(opened.recordVersion(),"cycle completed"),null);assertThat(closed.status()).isEqualTo("CLOSED");assertThatThrownBy(()->cycles.cancel("TEST-AGENCY",cycle.id(),new CycleTransition(closed.recordVersion(),"invalid"),null)).isInstanceOf(IllegalLifecycleTransitionException.class);}
 @Test void invalidCalendarAndOverlappingCycleAreRejected(){PolicyResponse draft=policies.create("TEST-AGENCY",policy("CAL",null),null);PolicyResponse policy=policies.publish("TEST-AGENCY",draft.id(),new PolicyTransition(draft.recordVersion(),LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"approved"),null);CycleResponse first=cycles.create("TEST-AGENCY",new CycleInput("A","A",LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),policy.id(),"Asia/Manila",null),null);MilestoneInput outside=new MilestoneInput(PerformanceCycleMilestone.Type.PLANNING_OPEN,"PLANNING_OPEN","Planning",Instant.parse("2025-12-01T00:00:00Z"),null,true,1,null,false);assertThatThrownBy(()->cycles.milestones("TEST-AGENCY",first.id(),new MilestonesInput(first.recordVersion(),List.of(outside)),null)).hasMessageContaining("inside");CycleResponse configured=cycles.milestones("TEST-AGENCY",first.id(),new MilestonesInput(first.recordVersion(),calendar()),null);CycleResponse second=cycles.create("TEST-AGENCY",new CycleInput("B","B",LocalDate.of(2026,6,1),LocalDate.of(2026,12,31),policy.id(),"Asia/Manila",null),null);assertThatThrownBy(()->cycles.open("TEST-AGENCY",configured.id(),new CycleTransition(configured.recordVersion(),"open"),null)).hasMessageContaining("overlaps");cycles.cancel("TEST-AGENCY",second.id(),new CycleTransition(second.recordVersion(),"duplicate draft"),null);assertThat(cycles.open("TEST-AGENCY",configured.id(),new CycleTransition(configured.recordVersion(),"open"),null).status()).isEqualTo("OPEN");}
 private static PolicyInput policy(String code,Long version){return new PolicyInput(code,"Agency SPMS",null,"CSC SPMS and agency policy","SPMS",PerformancePolicyVersion.Frequency.ANNUAL,false,false,false,false,false,version);}
 private static List<MilestoneInput>calendar(){PerformanceCycleMilestone.Type[] types={PerformanceCycleMilestone.Type.PLANNING_OPEN,PerformanceCycleMilestone.Type.PLANNING_DUE,PerformanceCycleMilestone.Type.APPROVAL_DUE,PerformanceCycleMilestone.Type.MONITORING_START,PerformanceCycleMilestone.Type.ACCOMPLISHMENT_DUE,PerformanceCycleMilestone.Type.RATING_DUE,PerformanceCycleMilestone.Type.FINALIZATION_DUE};List<MilestoneInput> result=new ArrayList<>();for(int i=0;i<types.length;i++){Instant at=Instant.parse("2026-01-01T00:00:00Z").plus(i*40L,java.time.temporal.ChronoUnit.DAYS);result.add(new MilestoneInput(types[i],types[i].name(),types[i].name(),at,null,true,i+1,null,false));}return result;}
}
